/// Opens [url] in the platform's browser when it is an https URL.
void _openLink(String url) {
  final uri = Uri.tryParse(url);
  if (uri != null && uri.scheme == 'https' && uri.host.isNotEmpty) {
    unawaited(launchUrl(uri, mode: LaunchMode.externalApplication));
  }
}

/// The image `![alt](url)` draws: only an address `image(url: ...)` draws (an https address, or a
/// path of the app's API), else the alt text. The package would otherwise fetch any `http` URL.
Widget _image(String url, Map<String, String> attributes) {
  final alt = attributes['alt'] ?? '';
  final address = cruftfreeSafeImageUrl(url, cruftfreeRuntime.config.apiBaseUrl.toString());
  if (address == null) {
    return Text(alt);
  }
  return Image.network(address, semanticLabel: alt.isEmpty ? null : alt, excludeFromSemantics: alt.isEmpty);
}

/// The anchor [text] derives, told apart from every anchor in [taken], which it joins.
String headingAnchor(String text, Set<String> taken) {
