class CruftFreeMarkdown extends StatefulWidget {
  const CruftFreeMarkdown({super.key, required this.source, this.style});

  final String source;
  final CruftFreeStyle? style;

  @override
  State<CruftFreeMarkdown> createState() => _CruftFreeMarkdownState();
}

/// Every heading carries an anchor, derived from its text by the one rule every
/// target realizes: its text, code and raw-HTML content (an image and a line
/// break each a separator), every run outside ASCII letters and digits one '-',
/// trimmed, lowercased, after 'h-' ('h-section' when nothing is left), and a
/// repeat within the document suffixed '-2', '-3', ... until it is free. An
/// in-page link (`#h-...`) scrolls to its heading; every other link opens
/// through [_openLink].
class _CruftFreeMarkdownState extends State<CruftFreeMarkdown> {
  /// The key of each rendered block holding a heading, by block index.
  final Map<int, GlobalKey> _blocks = {};

  /// The block index of each heading's anchor, as the last build derived them.
  Map<String, int> _anchors = const {};

  void _follow(String url) {
    if (!url.startsWith('#')) {
      _openLink(url);
      return;
    }
    final block = _anchors[url.substring(1)];
    final target = block == null ? null : _blocks[block]?.currentContext;
    if (target != null) {
      unawaited(Scrollable.ensureVisible(target));
    }
  }

  @override
  Widget build(BuildContext context) {
    var headings = const <Toc>[];
    final blocks = MarkdownGenerator(
      generators: [SpanNodeGeneratorWithTag(tag: MarkdownTag.code.name, generator: (element, config, visitor) => _CodeSpan(element.textContent, config.code))],
    ).buildWidgets(widget.source, config: _themedConfig(context, _follow, cruftfreeFontScale(context, widget.style)), onTocList: (found) => headings = found);
    final taken = <String>{};
    _anchors = {for (final heading in headings) headingAnchor(heading.node.childrenSpan.toPlainText(includeSemanticsLabels: false), taken): heading.widgetIndex};
    final anchored = _anchors.values.toSet();
    final column = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [for (final (index, block) in blocks.indexed) anchored.contains(index) ? KeyedSubtree(key: _blocks.putIfAbsent(index, GlobalKey.new), child: block) : block],
    );
    return cruftfreeStyled(context, widget.style, SelectionArea(child: column));
  }
}

/// A toolbar action: what it inserts, its framework text and its glyph.
enum _Formatting {
  bold('framework.bold', Icons.format_bold),
  italic('framework.italic', Icons.format_italic),
  link('framework.link', Icons.link),
  bulletedList('framework.bulletedList', Icons.format_list_bulleted);

  const _Formatting(this.labelKey, this.icon);

  final String labelKey;
  final IconData icon;

  /// [selected] with this formatting applied.
  String apply(String selected) {
    return switch (this) {
      _Formatting.bold => '**$selected**',
      _Formatting.italic => '_${selected}_',
      _Formatting.link => '[$selected]()',
      _Formatting.bulletedList => selected.split('\n').map((line) => '- $line').join('\n'),
    };
  }
}

