class _CruftFreeMarkdownEditorState extends State<CruftFreeMarkdownEditor> {
  late final TextEditingController _controller = TextEditingController(text: widget.value ?? '');

  @override
  void didUpdateWidget(CruftFreeMarkdownEditor oldWidget) {
    super.didUpdateWidget(oldWidget);
    final value = widget.value;
    if (value != null && value != _controller.text) {
      _controller.text = value;
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _changed(String text) {
    setState(() {});
    widget.onChanged?.call(text);
    widget.onChange?.call();
  }

  void _format(_Formatting formatting) {
    final text = _controller.text;
    final selection = _controller.selection;
    final start = selection.isValid ? selection.start : text.length;
    final end = selection.isValid ? selection.end : text.length;
    final replacement = formatting.apply(text.substring(start, end));
    _controller.value = TextEditingValue(
      text: text.replaceRange(start, end, replacement),
      selection: TextSelection(baseOffset: start, extentOffset: start + replacement.length),
    );
    _changed(_controller.text);
  }

  @override
  Widget build(BuildContext context) {
    final messages = cruftfreeRuntime.messages;
    final hint = widget.placeholder;
    final editor = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      spacing: CruftFreeTokens.of(context).gap,
      children: [
        Semantics(
          container: true,
          label: messages.key('framework.formatting').text,
          explicitChildNodes: true,
          child: Wrap(
            children: [for (final formatting in _Formatting.values) IconButton(icon: Icon(formatting.icon), tooltip: messages.key(formatting.labelKey).text, onPressed: widget.enabled ? () => _format(formatting) : null)],
          ),
