        TextField(
          controller: _controller,
          enabled: widget.enabled,
          decoration: InputDecoration(labelText: widget.label, hintText: hint == null || hint.isEmpty ? null : hint),
          keyboardType: TextInputType.multiline,
          minLines: 4,
          maxLines: null,
          onChanged: _changed,
        ),
        Semantics(
          container: true,
          label: messages.key('framework.preview').text,
          explicitChildNodes: true,
          child: CruftFreeMarkdown(source: _controller.text),
        ),
      ],
    );
    return cruftfreeStyled(context, widget.style, editor);
  }
